using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpServer.Tools;

/// <summary>
/// MCP tools are discovered by the SDK via [McpServerToolType] on the class
/// and [McpServerTool] on each method. Constructor parameters are resolved
/// from the DI container automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The SDK resolves constructor dependencies from IServiceProvider.
    // Because we register a named HttpClient ("WeatherApi"), we inject
    // IHttpClientFactory and create the client manually, OR we can use
    // a typed client pattern. Here we use IHttpClientFactory for clarity.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClient = httpClientFactory.CreateClient("WeatherApi");
    }

    [McpServerTool, Description("Get the current weather for a city.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetAsync(
            $"/v1/current?city={Uri.EscapeDataString(city)}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-7)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetAsync(
            $"/v1/forecast?city={Uri.EscapeDataString(city)}&days={days}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }
}

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpServer.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();  // Discovers all [McpServerToolType] classes

// Register a named HttpClient that WeatherTools will consume via DI.
builder.Services.AddHttpClient("WeatherApi", client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

var app = builder.Build();
await app.RunAsync();

